/// Read-model baseline canned from the fixture pool: the catalog offers pricing reads and
/// the canonical OrderTracking rows the saga legs read (`read_order`) — state the spec's
/// GIVEN (an event list) cannot express but its cases assume.
async fn spec_baseline(bed: &TestBed) {
    support::install_catalog_offers(bed, &fx_product_added());
    support::install_catalog_offers(bed, &fx_catalog_imported());
    if let DomainEvent::OrderPlaced(op) = fx_order_placed() {
        bed.orders.upsert(support::tracking_row_from_order_placed(&op));
    }
    if let DomainEvent::OrderPlaced(op) = fx_order_placed_replacement() {
        bed.orders.upsert(support::tracking_row_from_order_placed(&op));
    }
}

